#include <iostream>
#include <fstream>
#include <string>
#include <map>
using namespace std;

int main() {
    ifstream plik("transakcje.txt");
    string data, klient;
    int kwota;
    map<string, int> obrotKlient;
    map<string, int> obrotMiesiac;

    while (plik >> data >> klient >> kwota) {
        obrotKlient[klient] += kwota;
        obrotMiesiac[data.substr(0, 7)] += kwota;
    }

    cout << "a) Obrót klientow:" << endl;
    string maxKlient; int maxKwKlient = 0;
    for (auto &p : obrotKlient) {
        cout << "   " << p.first << ": " << p.second << endl;
        if (p.second > maxKwKlient) {
            maxKwKlient = p.second;
            maxKlient = p.first;
        }
    }

    cout << endl << "b) Obrót miesieczny:" << endl;
    string maxMiesiac; int maxKwMiesiac = 0;
    for (auto &p : obrotMiesiac) {
        cout << "   " << p.first << ": " << p.second << endl;
        if (p.second > maxKwMiesiac) {
            maxKwMiesiac = p.second;
            maxMiesiac = p.first;
        }
    }

    cout << endl << "c) Najlepszy klient: " << maxKlient << " (" << maxKwKlient << ")" << endl;
    cout << "   Najlepszy miesiac: " << maxMiesiac << " (" << maxKwMiesiac << ")" << endl;
    return 0;
}
```

